files.content:
* {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  background-color: #fff;
  block-size: 100%;
  min-inline-size: 360px;
  filter: invert(1);
}

.header {
  background-color: #fff;
  inline-size: 100%;
}

.header__title {
  margin: 0;
  border: 1px solid #000;
  padding: 20px 0;
  font-weight: 800;
  font-size: 38px;
  text-align: center;
  text-transform: uppercase;
  -webkit-hyphens: auto;
  hyphens: auto;
}

.menu {
  border-inline-start: 1px solid #000;
  border-inline-end: 1px solid #000;
}

.menu__list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  place-items: center;
  margin: 0;
  padding: 0;
  list-style: none;
  inline-size: 100%;
}

.menu__item {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 20px 10px;
  cursor: pointer;
  inline-size: 100%;
  block-size: 100%;
}

.menu__item:not(:last-of-type) {
  border-inline-end: 1px solid #000;
}

.menu__item a {
  position: relative;
  display: block;
  margin: 0;
  font-weight: 800;
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
}

.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid #000;
  inline-size: 100%;
}

.card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: 20px;
  background-color: white;
}

.card:not(:last-of-type) {
  border-inline-end: 1px solid #000;
}

.card__image {
  border: 1px solid #000;
  inline-size: 100%;
}

.card__title {
  align-self: flex-start;
  font-weight: 400;
  font-size: 16px;
}

.card__description {
  -webkit-hyphens: auto;
  hyphens: auto;
  inline-size: 100%;
}

.card:nth-child(1) {
  background-color: #c4c4c4;
}

.card:nth-child(2) {
  background-color: #feafe8;
}

.card:nth-child(3) {
  background-color: #80d994;
}

.card__button {
  border: 1px solid #000;
  padding: 20px 0;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #fff;
  inline-size: 100%;
}

.card__button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__button:focus-visible {
  outline: 2px solid #000;
  outline-offset: 0;
}

@media (width <= 600px) {
  body {
    display: block;
    padding: 10px;
  }

  .header__title {
    font-size: 24px;
  }

  .menu__list {
    grid-template-columns: 1fr;
  }

  .menu__item a {
    font-size: 18px;
  }

  .menu__item:not(:last-of-type) {
    border-inline-end: none;
    border-block-end: 1px solid #000;
  }

  .container {
    grid-template-columns: 1fr;
  }

  .card:not(:last-of-type) {
    border-inline-end: none;
    border-block-end: 1px solid #000;
  }
}
